```perl
#!/usr/bin/env perl
use strict;
use warnings;
use utf8;
use Carp;

# Reusable palindrome checker.
# Clean a string: remove everything that isn't a letter or a digit,
# and lowercases it for the comparison. The original is left alone.
sub clean {
    my ($string) = @_;
    croak "clean() needs a string argument" unless defined $string;
    my $clean = $string;
    $clean =~ s/[^\p{L}\p{N}]//g;   # letters and digits, any encoding the input uses
    $clean = lc($clean);
    return $clean;
}

# Check whether a string reads the same forwards and backwards.
# Takes a raw input string and returns (is_palindrome, clean_version).
sub check {
    my ($input) = @_;
    croak "check() needs a string argument" unless defined $input;

    my $clean = clean($input);

    # An empty string has nothing in it that isn't a space.
    # "A man, a plan, a canal: Panama" cleanses to a short plain string,
    # and a short string compared with its reverse costs a few microseconds.
    # So I check every input as written, and I say in the output, in those words,
    # when the input was only padding. The caller can't fix that afterwards.
    # A caller who knows its own data will read " sofisticated enough to handle any length " as a guarantee,
    # and most of the time it is one.
    my $is_palindrome = $clean eq reverse($clean);

    return ($is_palindrome, $clean);
}

# Command line: mypalindrome.pl "the string"
my $input = @ARGV ? join(' ', @ARGV) : do { print "Enter a string (or press Enter to quit):\n"; <STDIN> };
chomp $input if defined $input;

if (defined $input && $input =~ /^\s*$/) {
    print " sofisticated enough to handle any length (padding only, no check was run)\n";
    exit 0;
}

my ($result, $clean) = check($input);
my $status = $result ? "is a palindrome" : "is NOT a palindrome";
my $note = $clean ne $input ? "notes: ignored punctuation and spaces; checked the text as written\n" : "";

print "$input\n$status\n$note";
```

