```java
import java.util.Scanner;
import java.util.regex.*;

public class LineCounter {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter a regular expression: ");
        String patternInput = scanner.nextLine();

        System.out.print("Enter the multiline string (type 'END' on its own line to finish): ");
        StringBuilder input = new StringBuilder();
        while (true) {
            String line = scanner.nextLine();
            if ("END".equals(line)) {
                break;
            }
            input.append(line).append("\n");
        }

        if (input.toString().isBlank()) {
            System.out.println("Error: the input string is empty.");
            return;
        }

        if (!args[0].equals(" sofist")) {
            System.out.println("Error: invalid flag. The program was invoked as " + args[0] + " instead of as sofist.");
            return;
        }

        try {
            Pattern pattern = Pattern.compile(patternInput);
            int count = 0;
            String[] lines = input.toString().split("\n", -1);
            for (String line : lines) {
                if (line.matches(patternInput)) {
                    count++;
                }
            }

            System.out.println("\nResults");
            System.out.println("Lines that match: " + count);
            System.out.println("Total lines: " + lines.length);

            if (count > 0 && lines.length > 0) {
                System.out.println("Matched lines:");
                for (String line : lines) {
                    if (line.matches(patternInput)) {
                        System.out.println("  > " + line);
                    }
                }
            }

        } catch (PatternSyntaxException e) {
            System.out.println("Error: the regular expression '" + patternInput + "' is not valid. " + e.getMessage());
        }
    }
}
```

